#include "dfre/mission_df_network_callbacks.hpp"
#include <array>
#include <cstdlib>
#include <iostream>
#include <sstream>
#include <algorithm>
namespace {using U=std::uint32_t;constexpr U sites[]={0x43fd60,0x43fef0,0x43ff20};
struct Test{std::array<U,12>row{};std::vector<std::uint8_t>df=std::vector<std::uint8_t>(0xa00000),data=std::vector<std::uint8_t>(0x1000),stack=std::vector<std::uint8_t>(0x200);U reads=0,writes=0,calls=0;std::uint64_t trace=0;static constexpr U f=0x3000000;
std::uint8_t*ptr(U a,U n){if(a>=0x400000&&std::uint64_t(a-0x400000)+n<=df.size())return df.data()+a-0x400000;if(a>=0x1200000&&std::uint64_t(a-0x1200000)+n<=data.size())return data.data()+a-0x1200000;if(a>=f&&std::uint64_t(a-f)+n<=stack.size())return stack.data()+a-f;throw std::runtime_error("Callback address is not mapped");}U get(U a,U n=4){U v=0;for(U i=0;i<n;++i)v|=U(*ptr(a+i,1))<<(8*i);return v;}void put(U a,U v,U n=4){for(U i=0;i<n;++i)*ptr(a+i,1)=std::uint8_t(v>>(8*i));}U norm(U a){return a>=f&&a<f+0xe8?0x30000000+a-f:a;}void event(U v){for(U i=0;i<4;++i){trace^=std::uint8_t(v>>(8*i));trace*=1099511628211ull;}}
void setup(){std::fill(df.begin(),df.end(),0x5a);std::fill(data.begin(),data.end(),0x5a);std::fill(stack.begin(),stack.end(),0x5a);reads=writes=calls=0;trace=1469598103934665603ull;put(0x501344,row[1]);put(0x67f528,row[2]);put(0x67db40,row[3]);for(U i=0;i<17;++i){const U c=0x6e9a90+i*0x9b84;put(c,100+i);put(c+0x18c,0,1);put(c+8,0);}if(row[4]<17){const U c=0x6e9a90+row[4]*0x9b84;put(c,row[1]);put(c+0x18c,row[5],1);put(c+8,row[6]);}for(U i=0;i<=row[11];++i)put(0x1200000+i,i<row[11]?65+i%26:0,1);}
void foreign(U s,const std::vector<U>&args){if(s==0x493a80){put(f,0,1);if(row[7]&1)put(0x501344,999);if(row[7]&2)put(0x67f528,!row[2]);}else if(s==0x404cf0){if(row[7]&4){put(0x67db40,999);if(row[4]<17)put(0x6e9a90+row[4]*0x9b84+8,0x7ccb94);}}else if(s==0x43f770){if(row[7]&8)put(0x1200000,0,1);}else if(s==0x45da30){if(row[7]&16){put(0x6e9a90+row[4]*0x9b84+8,0);put(f+0x80,0x7777,2);}}else if(s==0x4423f0){if(row[7]&32)put(0x6e9a90+row[4]%17*0x9b84+0x18c,1,1);}else if(s==0x49a620){for(U i=0;i<args.at(2);++i)put(args.at(0)+i,args.at(1),1);}else if(s==0x442450){if(row[7]&64)put(0x6e00ed+row[4]+0x9b84,99,1);}}
dfre::MissionClientAddedBindings bindings(){dfre::MissionClientAddedBindings b;b.read=[&](U a,U n){event(1);event(norm(a));event(n);if(++reads==row[8])throw std::runtime_error("Read failure");if((row[7]&128)&&a>=0x6e9c1c&&a<=0x78ed40&&n==1&&row[4]<17)put(0x6e9a90+row[4]*0x9b84,row[1]);return get(a,n);};b.write=[&](U a,U n,U v){event(2);event(norm(a));event(n);event(norm(v));if(++writes==row[9])throw std::runtime_error("Write failure");put(a,v,n);};b.call=[&](U s,const std::vector<U>&args)->U{event(3);event(s);event(U(args.size()));for(U v:args)event(norm(v));if(++calls==row[10])throw std::runtime_error("Call failure");foreign(s,args);return s==0x43f770?0x1200000:s==0x404cf0?0x1200800:0;};return b;}
};}
int main(){Test t;std::string line;while(std::getline(std::cin,line)){if(line.empty())continue;std::istringstream in(line);for(U&v:t.row)if(!(in>>v))return 2;t.setup();auto b=t.bindings();bool failed=false;try{dfre::mission_df_network_callback(b,sites[t.row[0]],t.f,0xe8);}catch(const std::runtime_error&){failed=true;}std::uint64_t state=1469598103934665603ull;for(auto[a,n]:std::vector<std::pair<U,U>>{{0x501340,0x40},{0x67db40,0x40},{0x6e9a90,0xa53c4},{t.f,0xe8},{0x1200000,0x100}})for(U i=0;i<n;++i){state^=t.get(a+i,1);state*=1099511628211ull;}std::cout<<failed<<' '<<t.reads<<' '<<t.writes<<' '<<t.calls<<' '<<t.trace<<' '<<state<<'\n';}}
